import pytest
from subject import (
    EnumFileType,
    ModelTaskShapeContext,
    ModelTaskShapeFeatures,
    extract_task_shape,
)

@pytest.mark.unit
def test_extract_task_shape_none_context():
    assert extract_task_shape(None) == ModelTaskShapeFeatures()

@pytest.mark.unit
def test_extract_task_shape_all_defaults():
    ctx = ModelTaskShapeContext()
    assert extract_task_shape(ctx) == ModelTaskShapeFeatures()

@pytest.mark.unit
def test_extract_task_shape_diff_size():
    ctx = ModelTaskShapeContext(diff_lines_added=5, diff_lines_removed=3)
    assert extract_task_shape(ctx).diff_size == 8

@pytest.mark.unit
def test_extract_task_shape_file_types():
    ctx = ModelTaskShapeContext(
        file_paths=("a.py", "b.ts", "c.tsx", "d.yaml", "e.yml", "f.md", "g.txt")
    )
    expected = frozenset(
        {
            EnumFileType.PYTHON,
            EnumFileType.TYPESCRIPT,
            EnumFileType.YAML,
            EnumFileType.MARKDOWN,
            EnumFileType.OTHER,
        }
    )
    assert extract_task_shape(ctx).file_types == expected

@pytest.mark.unit
def test_extract_task_shape_file_types_duplicates():
    ctx = ModelTaskShapeContext(file_paths=("a.py", "b.py", "c.py"))
    assert extract_task_shape(ctx).file_types == frozenset({EnumFileType.PYTHON})

@pytest.mark.unit
def test_extract_task_shape_file_types_no_extension():
    ctx = ModelTaskShapeContext(file_paths=("README", "Makefile"))
    assert extract_task_shape(ctx).file_types == frozenset({EnumFileType.OTHER})

@pytest.mark.unit
def test_extract_task_shape_novelty_score_provided():
    ctx = ModelTaskShapeContext(ledger_novelty_score=0.8)
    assert extract_task_shape(ctx).novelty_score == 0.8

@pytest.mark.unit
def test_extract_task_shape_novelty_score_default():
    ctx = ModelTaskShapeContext()
    assert extract_task_shape(ctx).novelty_score == 0.5

@pytest.mark.unit
def test_extract_task_shape_combined():
    ctx = ModelTaskShapeContext(
        diff_lines_added=10,
        diff_lines_removed=5,
        file_paths=("src/main.py", "tests/test.ts", "docs/README.md"),
        ledger_novelty_score=0.2,
    )
    features = extract_task_shape(ctx)
    assert features.diff_size == 15
    assert features.file_types == frozenset(
        {EnumFileType.PYTHON, EnumFileType.TYPESCRIPT, EnumFileType.MARKDOWN}
    )
    assert features.novelty_score == 0.2
